<?php

declare(strict_types=1);

namespace App\Context\Billing\Domain\ValueObject;

enum InvoiceLineSource: string
{
    /** Snapshotted from a consultation's billing lines. */
    case CONSULTATION = 'CONSULTATION';

    /** Typed by hand at the desk. */
    case MANUAL = 'MANUAL';

    /** Generated by the invoice itself, e.g. a discount line. */
    case ADJUSTMENT = 'ADJUSTMENT';
}
